package main

import (
	"context"
	"fmt"
	"os"
	"strconv"
	"syscall"

	"github.com/ava-labs/avalanchego/utils/logging"
	"github.com/ava-labs/avalanchego/utils/ulimit"
	"github.com/ava-labs/avalanchego/version"
	"github.com/ava-labs/avalanchego/vms/rpcchainvm"
	"github.com/ava-labs/subnet-evm/plugin/evm"
	"github.com/ava-labs/subnet-evm/plugin/runner"

	// Each precompile generated by the precompilegen tool has a self-registering init function
	// that registers the precompile with the subnet-evm. Importing the precompile package here
	// will cause the precompile to be registered with the subnet-evm.
	_ "github.com/fredericosanntana/dpo2u-avalanche/l1/precompile/midnightverifier"
)

// Version of this DPO2U build of Precompile-EVM v0.4.0 (adds the Midnight verifier).
const Version = "v0.4.0-dpo2u.a2"

// fdLimitEnv overrides the file descriptor limit the VM asks for (default 32768, as upstream).
// Where the host's hard limit is lower (some containers), upstream exits at start; this build
// asks for the hard limit instead. Validators should keep a hard limit >= 32768.
const fdLimitEnv = "DPO2U_VM_FD_LIMIT"

func main() {
	evm.RegisterAllLibEVMExtras()
	versionString := fmt.Sprintf("DPO2U-Precompile-EVM/%s Subnet-EVM/%s [AvalancheGo=%s, rpcchainvm=%d]", Version, evm.Version, version.Current, version.RPCChainVMProtocol)

	// Same as subnet-evm's runner.Run, with the fd limit configurable.
	printVersion, err := runner.PrintVersion()
	if err != nil {
		fmt.Printf("couldn't get config: %s", err)
		os.Exit(1)
	}
	if printVersion {
		fmt.Println(versionString)
		os.Exit(0)
	}
	limit := uint64(ulimit.DefaultFDLimit)
	if v := os.Getenv(fdLimitEnv); v != "" {
		if limit, err = strconv.ParseUint(v, 10, 64); err != nil {
			fmt.Printf("invalid %s: %s", fdLimitEnv, err)
			os.Exit(1)
		}
	}
	var rl syscall.Rlimit
	if err := syscall.Getrlimit(syscall.RLIMIT_NOFILE, &rl); err == nil && rl.Max < limit {
		fmt.Fprintf(os.Stderr, "fd limit %d above the hard limit %d; using %d\n", limit, rl.Max, rl.Max)
		limit = rl.Max
	}
	if err := ulimit.Set(limit, logging.NoLog{}); err != nil {
		fmt.Printf("failed to set fd limit correctly due to: %s", err)
		os.Exit(1)
	}
	rpcchainvm.Serve(context.Background(), &evm.VM{})
}
